"""Generate Unicode 15.0.0 excluded-category ranges for names.

Run from the repository root with Python 3.12: python -I internal/names/testdata/ucd15_gen.py
"""

import sys
import unicodedata
from pathlib import Path


if unicodedata.unidata_version != "15.0.0":
    raise SystemExit("ucd15_gen.py requires Python Unicode database 15.0.0")

excluded = {"Cc", "Cf", "Cn", "Co", "Cs", "Zl", "Zp"}
ranges = []
start = None
last = None
for codepoint in range(0x110000):
    if unicodedata.category(chr(codepoint)) in excluded:
        if start is None:
            start = codepoint
        last = codepoint
    elif start is not None:
        ranges.append((start, last))
        start = None
if start is not None:
    ranges.append((start, last))

r16 = []
r32 = []
for lo, hi in ranges:
    if lo <= 0xFFFF:
        r16.append((lo, min(hi, 0xFFFF)))
    if hi > 0xFFFF:
        r32.append((max(lo, 0x10000), hi))

lines = [
    "// Code generated by ucd15_gen.py; DO NOT EDIT.",
    f"// Python {'.'.join(map(str, sys.version_info[:3]))}; Unicode {unicodedata.unidata_version}.",
    "",
    "package names",
    "",
    'import "unicode"',
    "",
    "var ucd15Excluded = &unicode.RangeTable{",
    "\tR16: []unicode.Range16{",
]
lines.extend(f"\t\t{{Lo: 0x{lo:04X}, Hi: 0x{hi:04X}, Stride: 1}}," for lo, hi in r16)
lines.extend(["\t},", "\tR32: []unicode.Range32{"])
lines.extend(f"\t\t{{Lo: 0x{lo:06X}, Hi: 0x{hi:06X}, Stride: 1}}," for lo, hi in r32)
lines.extend(["\t},", f"\tLatinOffset: {sum(hi <= 0x00FF for _, hi in r16)},", "}", ""])
output = Path(__file__).resolve().parent.parent / "ucd15.go"
output.write_text("\n".join(lines), encoding="utf-8", newline="\n")
